import type { ChatTurn, CompanionFact, CompanionLanguage } from "@shared/companionContext";
import type { CompanionPersona } from "@shared/persona";
import { demoReply } from "./demoCompanion";

export interface CompanionReply {
  text: string;
  /** "gemini" = generated by Google Gemini. "scripted" = explicit local Demo text, never AI. */
  source: "gemini" | "scripted";
}

/** The real AI service could not answer. Callers must show this state, never a scripted substitute. */
export class CompanionServiceUnavailableError extends Error {
  constructor() {
    super("Pookie's AI service is unavailable");
    this.name = "CompanionServiceUnavailableError";
  }
}

export interface CompanionRequest {
  mode: "demo" | "firebase";
  turns: readonly ChatTurn[];
  language: CompanionLanguage;
  /** Used only for scripted replies; the Cloud Function loads its own facts server-side. */
  facts: readonly CompanionFact[];
  preferredName: string;
  /** Used only for scripted replies; the Cloud Function reads the persona from the stored profile. */
  persona: CompanionPersona;
}

const SCRIPTED_DELAY_MS = 600;
const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

function scripted(request: CompanionRequest): CompanionReply {
  const userTurns = request.turns.filter((t) => t.role === "user");
  const last = userTurns[userTurns.length - 1]?.text ?? "";
  return {
    text: demoReply({ text: last, facts: request.facts, language: request.language, preferredName: request.preferredName, turn: userTurns.length - 1, persona: request.persona }),
    source: "scripted",
  };
}

/**
 * Gets Pookie's next reply. With Firebase configured this calls the
 * `companionReply` Cloud Function (Gemini, key held server-side). Scripted
 * replies exist only in explicit local Demo Mode. A production service failure
 * is surfaced to the caller so it can be explained honestly.
 */
export async function requestCompanionReply(request: CompanionRequest): Promise<CompanionReply> {
  if (request.mode === "demo") {
    await wait(SCRIPTED_DELAY_MS);
    return scripted(request);
  }
  try {
    const [{ httpsCallable }, { getFirebase }] = await Promise.all([import("firebase/functions"), import("@/lib/firebase/client")]);
    const call = httpsCallable<{ messages: readonly ChatTurn[]; language: CompanionLanguage }, { text: string }>(getFirebase().functions, "companionReply");
    const result = await call({ messages: request.turns, language: request.language });
    return { text: result.data.text, source: "gemini" };
  } catch {
    throw new CompanionServiceUnavailableError();
  }
}

/** Audio for one reply in the companion's own Cloud voice. Null when unavailable (the caller falls back). */
export async function requestCompanionVoice(text: string, language: CompanionLanguage): Promise<string | null> {
  try {
    const [{ httpsCallable }, { getFirebase }] = await Promise.all([import("firebase/functions"), import("@/lib/firebase/client")]);
    const call = httpsCallable<{ text: string; language: CompanionLanguage }, { audio: string; mime: string }>(getFirebase().functions, "speak");
    const result = await call({ text, language });
    return result.data.audio ? `data:${result.data.mime};base64,${result.data.audio}` : null;
  } catch {
    return null;
  }
}
